    input  wire [STRB_WIDTH-1:0]  s_axil_wstrb,
    input  wire                   s_axil_wvalid,
    output wire                   s_axil_wready,
    output wire [1:0]             s_axil_bresp,
    output wire                   s_axil_bvalid,
    input  wire                   s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]  s_axil_araddr,
    input  wire [2:0]             s_axil_arprot,
    input  wire                   s_axil_arvalid,
    output wire                   s_axil_arready,
    output wire [DATA_WIDTH-1:0]  s_axil_rdata,
    output wire [1:0]             s_axil_rresp,
    output wire                   s_axil_rvalid,
    input  wire                   s_axil_rready,
    /*
     * AXI lite master interface
     */
    input  wire                   m_clk,
    input  wire                   m_rst,
    output wire [ADDR_WIDTH-1:0]  m_axil_awaddr,
    output wire [2:0]             m_axil_awprot,
    output wire                   m_axil_awvalid,
    input  wire                   m_axil_awready,
    output wire [DATA_WIDTH-1:0]  m_axil_wdata,
    output wire [STRB_WIDTH-1:0]  m_axil_wstrb,
    output wire                   m_axil_wvalid,
    input  wire                   m_axil_wready,
    input  wire [1:0]             m_axil_bresp,
    input  wire                   m_axil_bvalid,
    output wire                   m_axil_bready,
    output wire [ADDR_WIDTH-1:0]  m_axil_araddr,
    output wire [2:0]             m_axil_arprot,
    output wire                   m_axil_arvalid,
    input  wire                   m_axil_arready,
    input  wire [DATA_WIDTH-1:0]  m_axil_rdata,
    input  wire [1:0]             m_axil_rresp,
    input  wire                   m_axil_rvalid,
    output wire                   m_axil_rready
);

    // ========================================================================
    // Write Address Channel (AW) - S to M
    // ========================================================================
    wire [ADDR_WIDTH+2:0] aw_payload;
    assign aw_payload = {s_axil_awaddr, s_axil_awprot};

    wire aw_s2m_req;
    wire aw_s2m_ack;
    wire aw_m2s_req;
    wire aw_m2s_ack;

    // S to M synchronizer
    wire [1:0] aw_s2m_sync;
    reg [1:0] aw_s2m_sync_r;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            aw_s2m_sync_r <= 2'b00;
        else
            aw_s2m_sync_r <= {aw_s2m_sync_r[0], aw_s2m_req};
    end
    assign aw_s2m_sync = aw_s2m_sync_r;

    // M to S synchronizer
    wire [1:0] aw_m2s_sync;
    reg [1:0] aw_m2s_sync_r;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            aw_m2s_sync_r <= 2'b00;
        else
            aw_m2s_sync_r <= {aw_m2s_sync_r[0], aw_m2s_ack};
    end
    assign aw_m2s_sync = aw_m2s_sync_r;

    // S-side AW FSM
    reg aw_s_req;
    reg aw_s_ack;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            aw_s_req <= 1'b0;
            aw_s_ack <= 1'b0;
        end else begin
            if (aw_s_req && aw_m2s_sync[1]) begin
                aw_s_req <= 1'b0;
                aw_s_ack <= 1'b0;
            end else if (!aw_s_req && s_axil_awvalid && s_axil_awready) begin
                aw_s_req <= 1'b1;
            end
        end
    end
    assign aw_s2m_req = aw_s_req;
    assign s_axil_awready = !aw_s_req;

    // M-side AW FSM
    reg aw_m_req;
    reg aw_m_ack;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            aw_m_req <= 1'b0;
            aw_m_ack <= 1'b0;
        end else begin
            if (aw_m_req && aw_s2m_sync[1]) begin
                aw_m_req <= 1'b0;
                aw_m_ack <= 1'b0;
            end else if (!aw_m_req && aw_m2s_sync[1]) begin
                aw_m_req <= 1'b1;
            end
        end
    end
    assign aw_m2s_ack = aw_m_ack;
    assign m_axil_awvalid = aw_m_req;

    // ========================================================================
    // Write Data Channel (W) - S to M
    // ========================================================================
    wire [DATA_WIDTH+STRB_WIDTH:0] w_payload;
    assign w_payload = {s_axil_wdata, s_axil_wstrb};

    wire w_s2m_req;
    wire w_s2m_ack;
    wire w_m2s_req;
    wire w_m2s_ack;

    // S to M synchronizer
    wire [1:0] w_s2m_sync;
    reg [1:0] w_s2m_sync_r;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            w_s2m_sync_r <= 2'b00;
        else
            w_s2m_sync_r <= {w_s2m_sync_r[0], w_s2m_req};
    end
